package br.com.tapeteskalke.dto; import jakarta.validation.constraints.*; import java.math.BigDecimal; public final class ProdutoDtos { private ProdutoDtos(){} public record Request(@NotBlank @Size(max=180) String nome,@NotBlank String tipo,String categoria,String cor,String tamanho,@NotBlank String unidadeMedida,boolean podeSerVendido,boolean podeSerMateriaPrima,@DecimalMin("0.000") BigDecimal estoqueMinimoComercial,@DecimalMin("0.000") BigDecimal estoqueMinimoProducao,@DecimalMin("0.00") BigDecimal precoCusto,@DecimalMin("0.00") BigDecimal precoVenda,String codigoBarras,String fornecedorPrincipalId,String observacoes,boolean ativo){} public record Response(String id,String nome,String tipo,String unidadeMedida,boolean podeSerVendido,boolean podeSerMateriaPrima,BigDecimal estoqueComercial,BigDecimal estoqueProducao,BigDecimal estoqueMinimoComercial,BigDecimal estoqueMinimoProducao,BigDecimal precoVenda,String statusComercial,String statusProducao,boolean ativo,String categoria,String cor,String tamanho,BigDecimal precoCusto,String codigoBarras,String fornecedorPrincipalId,String observacoes){} public record AjusteRequest(@NotBlank String produtoId,@NotBlank @Pattern(regexp="COMERCIAL|PRODUCAO") String saldo,@NotNull @DecimalMin(value="-999999999.999",inclusive=false) BigDecimal quantidade,@NotBlank @Size(max=300) String observacao){} }